      omegnIdx[7] = pairsInGroup + ((8 * i + 7) % pairsInGroup);
      // printf("omegnIdx[0]:%llu ",omegnIdx[0]);

      left[0] = (1 - C) * (regs[0] - new_regs[0]) + new_regs[0];
      left[1] = (1 - C) * (regs[1] - new_regs[1]) + new_regs[1];
