    volatile __shared__ uint64_t carry;
    // uint64_t carrySum=0;
    volatile __shared__ uint64_t retail[2];

    // register uint64_t regs_carry;
    // new_regs3[0]=new_regs3[1]=0;
    // new_regs4[0]=0;

    regs0[0] = Aa1[0] >> u;
    regs0[1] = Aa1[1] >> u;
    regs0[2] = Aa1[2] >> u;
    regs0[3] = Aa1[3] >> u;
    regs0[4] = Aa1[4] >> u;
    regs0[5] = Aa1[5] >> u;
