// ================================================================
// FMLE 核函数（Algorithm 5: FFT-Based McLaughlin's Exponentiation）
//
// 共享内存布局（每 warp 512 个 uint64_t = 4096 bytes）：
//   ws[0..255]   : y_buf（标准形式）
//   ws[256..511] : t_buf（标准形式）
//
// 预计算参数（主机端准备好后传入，大小均为 256，所有 warp 共享）：
//   d_r0     : r₀ = r mod n
//   d_r1_ct  : CT(r₁)，其中 r₁ = r² mod n
//   d_r1_nct : NCT(r₁)
//
// 指数表示：exp_bits[i] = e[i]（0 或 1），i=0 为 LSB，i=tau-1 为 MSB
//
//
// ================================================================
__global__ void FMLEKernel(
    const uint64_t *__restrict__ A,         // [m*256] 输入 x（标准形式）
    const uint64_t *__restrict__ exp_bits,  // [tau]   指数位，e[0]=LSB
    int tau,                                // 指数位数
    uint64_t *output,                       // [m*256] 输出 t = x^e mod n
    int m,                                  // 大数个数
    // ---- 预计算常量（大小 256，所有 warp 共享，不按 warp 偏移）----
    const uint64_t *__restrict__ d_r0,  // r₀ = r mod n
    uint64_t *d_r1_ct,                  // CT(r₁)，r₁ = r² mod n
    uint64_t *d_r1_nct,                 // NCT(r₁)
    // ---- 模乘运算参数 ----
    uint64_t *negmodn, uint64_t *negmodn_shoup, uint64_t *modn,
    uint64_t *modn_shoup, uint64_t n_poly, uint64_t mod,
    const uint64_t *twiddle, const uint64_t *twiddle_shoup,
    const uint64_t *ICTTwiddle, const uint64_t *ICTTwiddle_shoup,
    const uint64_t *NCTtwiddle, const uint64_t *NCTtwiddle_shoup,
    const uint64_t *InvNCTtwiddle, const uint64_t *InvNCTtwiddle_shoup,
    uint64_t inv, uint64_t inv_shoup, const uint64_t *sample) {
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= m) return;

  // ---- 共享内存分区：每 warp 独占 512 个 uint64_t ----
  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const y_buf = ws;        // [256] y
  uint64_t *const t_buf = ws + 256;  // [256] t

  const int off = global_warp_id * 256;

// ================================================================
// Step 6: y ← x
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) y_buf[8 * lane_id + j] = A[off + 8 * lane_id + j];
  __syncwarp();

// ================================================================
// Step 7: t ← r₀
// d_r0 是全局共享常量（256个元素），所有 warp 读同一份，不偏移
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++) t_buf[8 * lane_id + j] = d_r0[8 * lane_id + j];
  __syncwarp();

  // ================================================================
  // Step 8: y ← FMLM(y, r₁)
  // 使用 XYfixWarpROneVector_dev
  // d_r1_ct / d_r1_nct 是全局共享，不按 warp 偏移（与之前验证一致）
  // ================================================================
  XYfixWarpROneVector_dev(y_buf, d_r1_ct, d_r1_nct,  // ← 全局共享，不偏移
                          negmodn, negmodn_shoup, modn, modn_shoup, n_poly, mod,
                          twiddle, twiddle_shoup, ICTTwiddle, ICTTwiddle_shoup,
                          NCTtwiddle, NCTtwiddle_shoup, InvNCTtwiddle,
                          InvNCTtwiddle_shoup, inv, inv_shoup, sample);
  __syncwarp();

  // ================================================================
  // Steps 9–12: for i = 0 to τ-1
  // exp_bits[i] 对 warp 内所有 lane 相同 → 无 warp 分歧
  // ================================================================
  for (int i = 0; i < tau; i++) {
    // Step 10: if e[i] = 1 then t ← FMLM(t, y)
    // 使用 XYfixWarpVector_dev：inout=t_buf（读写），inoutA=y_buf（只读）
    // t_buf 和 y_buf 是不同缓冲区，无别名问题
    if (exp_bits[i] == 1ULL) {
      XYfixWarpVector_dev(t_buf, y_buf,  // t = t × y
                          negmodn, negmodn_shoup, modn, modn_shoup, n_poly, mod,
                          twiddle, twiddle_shoup, ICTTwiddle, ICTTwiddle_shoup,
                          NCTtwiddle, NCTtwiddle_shoup, InvNCTtwiddle,
                          InvNCTtwiddle_shoup, inv, inv_shoup, sample);
      __syncwarp();
    }

    // Step 11: y ← FMLM(y, y)
    // 使用 XYfixWarpSquareVector_dev：原地平方
    XYfixWarpSquareVector_dev(y_buf,  // y = y × y
                              negmodn, negmodn_shoup, modn, modn_shoup, n_poly,
                              mod, twiddle, twiddle_shoup, ICTTwiddle,
                              ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                              InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                              inv_shoup, sample);
    __syncwarp();
  }

  // ================================================================
  // Step 13: t ← FMLM(t, 1)
  // 使用 XYfixWarpIRVector_dev：去除 Montgomery 因子，还原真实结果
  // ================================================================
  XYfixWarpIRVector_dev(t_buf,  // t = t × 1（去 Montgomery）
                        negmodn, negmodn_shoup, modn, modn_shoup, n_poly, mod,
                        twiddle, twiddle_shoup, ICTTwiddle, ICTTwiddle_shoup,
                        NCTtwiddle, NCTtwiddle_shoup, InvNCTtwiddle,
                        InvNCTtwiddle_shoup, inv, inv_shoup, sample);
  __syncwarp();

// ================================================================
// Step 14: return t → 写回全局内存
// ================================================================
#pragma unroll
  for (int j = 0; j < 8; j++)
    output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

__global__ void FMLEKernel_Debug(
    const uint64_t *__restrict__ A, const uint64_t *__restrict__ exp_bits,
    int tau, uint64_t *output, int m, const uint64_t *__restrict__ d_r0,
    uint64_t *d_r1_ct, uint64_t *d_r1_nct, uint64_t *negmodn,
    uint64_t *negmodn_shoup, uint64_t *modn, uint64_t *modn_shoup,
    uint64_t n_poly, uint64_t mod, const uint64_t *twiddle,
    const uint64_t *twiddle_shoup, const uint64_t *ICTTwiddle,
    const uint64_t *ICTTwiddle_shoup, const uint64_t *NCTtwiddle,
    const uint64_t *NCTtwiddle_shoup, const uint64_t *InvNCTtwiddle,
    const uint64_t *InvNCTtwiddle_shoup, uint64_t inv, uint64_t inv_shoup,
    const uint64_t *sample,
    // ---- 新增调试参数 ----
    uint64_t *debug_out,  // [6 * 256] 存储6个中间快照
    int debug_warp_id)    // 要调试的 warp 编号
{
  const int warp_in_block = threadIdx.x >> 5;
  const int warps_per_block = blockDim.x >> 5;
  const int global_warp_id = blockIdx.x * warps_per_block + warp_in_block;
  const uint32_t lane_id = threadIdx.x & 0x1F;

  if (global_warp_id >= m) return;

  extern __shared__ uint64_t smem[];
  uint64_t *const ws = smem + warp_in_block * 512;
  uint64_t *const y_buf = ws;
  uint64_t *const t_buf = ws + 256;

  const int off = global_warp_id * 256;

  // 是否是需要调试的 warp
  const bool is_debug = (global_warp_id == debug_warp_id);

// 快照宏：把 buf[0..255] 写入 debug_out 的第 slot 槽
#define SNAPSHOT(slot, buf)                                                 \
  if (is_debug) {                                                           \
    for (int _j = 0; _j < 8; _j++)                                          \
      debug_out[(slot) * 256 + 8 * lane_id + _j] = (buf)[8 * lane_id + _j]; \
    __syncwarp();                                                           \
  }

// ==================== Step 6: y = x ====================
#pragma unroll
  for (int j = 0; j < 8; j++) y_buf[8 * lane_id + j] = A[off + 8 * lane_id + j];
  __syncwarp();

  SNAPSHOT(0, y_buf)  // slot 0: y after Step6

// ==================== Step 7: t = r0 ====================
#pragma unroll
  for (int j = 0; j < 8; j++) t_buf[8 * lane_id + j] = d_r0[8 * lane_id + j];
  __syncwarp();

  SNAPSHOT(1, t_buf)  // slot 1: t after Step7

  // ==================== Step 8: y = FMLM(y, r1) ====================
  XYfixWarpROneVector_dev(y_buf, d_r1_ct, d_r1_nct, negmodn, negmodn_shoup,
                          modn, modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
  __syncwarp();

  SNAPSHOT(2, y_buf)  // slot 2: y after Step8

  // ==================== Loop: Steps 10 & 11 ====================
  for (int i = 0; i < tau; i++) {
    // Step 10: t = FMLM(t, y)
    if (exp_bits[i] == 1ULL) {
      XYfixWarpVector_dev(t_buf, y_buf, negmodn, negmodn_shoup, modn,
                          modn_shoup, n_poly, mod, twiddle, twiddle_shoup,
                          ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle,
                          NCTtwiddle_shoup, InvNCTtwiddle, InvNCTtwiddle_shoup,
                          inv, inv_shoup, sample);
      __syncwarp();

      // 只记录前4轮的 Step10 结果（slot 3 固定记录最后一次 t）
    }
    SNAPSHOT(3, t_buf)
    // Step 11: y = FMLM(y, y)
    XYfixWarpSquareVector_dev(y_buf, negmodn, negmodn_shoup, modn, modn_shoup,
                              n_poly, mod, twiddle, twiddle_shoup, ICTTwiddle,
                              ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
                              InvNCTtwiddle, InvNCTtwiddle_shoup, inv,
                              inv_shoup, sample);
    __syncwarp();

    if (i < 4) {
      SNAPSHOT(4, y_buf)  // slot 4: y after Step11（第 i 轮）
    }
  }

  // ==================== Step 13: t = FMLM(t, 1) ====================
  XYfixWarpIRVector_dev(
      t_buf, negmodn, negmodn_shoup, modn, modn_shoup, n_poly, mod, twiddle,
      twiddle_shoup, ICTTwiddle, ICTTwiddle_shoup, NCTtwiddle, NCTtwiddle_shoup,
      InvNCTtwiddle, InvNCTtwiddle_shoup, inv, inv_shoup, sample);
  __syncwarp();

  SNAPSHOT(5, t_buf)  // slot 5: t after Step13（最终结果）

#undef SNAPSHOT

// 写回最终输出
#pragma unroll
  for (int j = 0; j < 8; j++)
    output[off + 8 * lane_id + j] = t_buf[8 * lane_id + j];
}

__global__ void Testnctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                              uint64_t *twiddle, uint64_t *twiddle_shoup);

__global__ void Testnctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                              uint64_t *twiddle, uint64_t *twiddle_shoup) {
  __shared__ uint64_t buffer[256];
  for (uint64_t i = blockIdx.x * blockDim.x + threadIdx.x; i < n / 2;
       i += blockDim.x * gridDim.x) {
    uint64_t tid = i;

    uint64_t pairsInGroup;
    uint64_t k, j, glbIdx, glbIdxadd;  // k = psi_step
    uint64_t samples[2];
    uint64_t omgn, omgn_shoup;
    uint64_t twiddleId;

    for (uint64_t numOfGroups = 1; numOfGroups <= n / 2;
         numOfGroups = numOfGroups << 1) {
      pairsInGroup = n / numOfGroups / 2;

      k = tid / pairsInGroup;  // numOfGroups是这一轮NTT变换中的分组数
      j = tid % pairsInGroup;
      // pairInGroup 是每个分组中多少对; k=psi_step?  k是组号；j是对号
      glbIdx = 2 * k * pairsInGroup + j;
      glbIdxadd = glbIdx + pairsInGroup;  // 计算全局内存的索引

      // twiddleId=pairsInGroup+j;
      twiddleId = k + numOfGroups;
      omgn = twiddle[twiddleId];
      omgn_shoup = twiddle_shoup[twiddleId];

      if (numOfGroups == 1) {
        samples[0] = inout[glbIdx];
        samples[1] = inout[glbIdxadd];

      } else {
        samples[0] = buffer[glbIdx];
        samples[1] = buffer[glbIdxadd];
      }

      // CTbutter(samples[0],samples[1],mod,omgn);
      ct_butterfly(samples[0], samples[1], omgn, omgn_shoup, mod);

      if (numOfGroups == (n / 2)) {
        inout[glbIdx] = samples[0];

        inout[glbIdxadd] = samples[1];

      } else {
        buffer[glbIdx] = samples[0];

        buffer[glbIdxadd] = samples[1];

        __syncthreads();  // 线程同步
      }
    }
  }
}

__global__ void Testinctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                               uint64_t *twiddle, uint64_t *twiddle_shoup,
                               uint64_t inv, uint64_t inv_shoup);

__global__ void Testinctsample(uint64_t *inout, uint64_t n, uint64_t mod,
                               uint64_t *twiddle, uint64_t *twiddle_shoup,
                               uint64_t inv, uint64_t inv_shoup) {
  __shared__ uint64_t buffer[256];
  // uint64_t inv=ksm(n,mod-2,mod);
  for (uint64_t i = blockIdx.x * blockDim.x + threadIdx.x; i < n / 2;
       i += blockDim.x * gridDim.x) {
    uint64_t tid = i % (n / 2);
    uint64_t pairsInGroup;
    uint64_t k, j, glbIdx, glbIdxadd;  // k = psi_step
    uint64_t samples[2];
    uint64_t omgn, omgn_shoup;
    uint64_t twiddleId;

    for (uint64_t numOfGroups = n / 2; numOfGroups >= 1;
         numOfGroups = numOfGroups = numOfGroups / 2) {
      pairsInGroup = n / numOfGroups / 2;

      k = tid / pairsInGroup;  // numOfGroups是这一轮NTT变换中的分组数
      j = tid % pairsInGroup;
      // pairInGroup 是每个分组中多少对; k=psi_step?  k是组号；j是对号
      glbIdx = 2 * k * pairsInGroup + j;
      glbIdxadd = glbIdx + pairsInGroup;  // 计算全局内存的索引

      // twiddleId=pairsInGroup+j;
      twiddleId = k + numOfGroups;
      omgn = twiddle[twiddleId];
      omgn_shoup = twiddle_shoup[twiddleId];

      // printf("num:%llu ",numOfGroups);
      // printf("j:%llu ",j);
      // printf("tid:%llu ",tid);

      // printf("twiddleid:%llu ",twiddleId);
      // printf("pair:%llu ",pairsInGroup);
      // printf("glbIdx:%llu ",glbIdx);
      // printf("omgn:%llu ",omgn);
      // printf("glbIdxadd:%llu ",glbIdxadd);
      // uuint64_t psi_shoup = twiddles_shoup[numOfGroups + k + n * mod_idx];

      // printf("sample[glb]:%llu ",samples[0]);
      // printf("sample[glbIdxadd]:%llu ",samples[1]);
      if (numOfGroups == (n / 2)) {
        samples[0] = inout[glbIdx];
        samples[1] = inout[glbIdxadd];

      } else {
        samples[0] = buffer[glbIdx];
        samples[1] = buffer[glbIdxadd];
      }

      // GSbutter(samples[0],samples[1],mod,omgn);
      gs_butterfly(samples[0], samples[1], omgn, omgn_shoup, mod);
      // printf("Asample[glb]:%llu ",samples[0]);
      // printf("Asample[glbIdxadd]:%llu ",samples[1]);

      if (numOfGroups == 1) {
        inout[glbIdx] = samples[0];

        inout[glbIdxadd] = samples[1];
        inout[glbIdx] =
            multiply_and_reduce_shoup_lazy(inout[glbIdx], inv, inv_shoup, mod);
        inout[glbIdxadd] = multiply_and_reduce_shoup_lazy(inout[glbIdxadd], inv,
                                                          inv_shoup, mod);
        // inout[glbIdx]=ksc(inout[glbIdx],inv,mod);
        // inout[glbIdxadd]=ksc(inout[glbIdxadd],inv,mod);

      } else {
        buffer[glbIdx] = samples[0];

        buffer[glbIdxadd] = samples[1];
        __syncthreads();  // 线程同步
        // printf("inout[glb]:%llu ",inout[glbIdx]);
        // printf("inout[glbIdxadd]:%llu ",inout[glbIdxadd]);
      }
    }
  }
}

struct CommonDeviceArrays {
  uint64_t *d_negmodn, *d_negmodn_shoup;
  uint64_t *d_modn, *d_modn_shoup;
  uint64_t *d_twiddle, *d_twiddle_shoup;
  uint64_t *d_ICTTwiddle, *d_ICTTwiddle_shoup;
  uint64_t *d_NCTtwiddle, *d_NCTtwiddle_shoup;
  uint64_t *d_InvNCTtwiddle, *d_InvNCTtwiddle_shoup;
  uint64_t *d_sample;
  uint64_t n;
  uint64_t mod;
  uint64_t inv;
  uint64_t inv_shoup;
};

void multiStream(uint64_t *arrX, uint64_t *arrY, size_t n_streams,
                 CommonDeviceArrays &common) {
  const int num_elements_per_stream = 256;
  size_t chunk_bytes = num_elements_per_stream * sizeof(uint64_t);
  size_t total_bytes = n_streams * chunk_bytes;

  // 分配设备端的完整 arrX 和 arrY
  uint64_t *d_arrX, *d_arrY;
  cudaMalloc(&d_arrX, total_bytes);
  cudaMalloc(&d_arrY, total_bytes);

  // 创建 CUDA 流
  cudaStream_t streams[128];
  for (int i = 0; i < n_streams; i++) {
    cudaStreamCreate(&streams[i]);
  }

  // 分发任务：H2D拷贝 -> 内核执行 -> D2H拷贝
  for (int i = 0; i < n_streams; i++) {
    int offset = i * num_elements_per_stream;

    // 异步拷贝数据到 GPU
    // cudaMemcpyAsync(&d_arrX[offset], &arrX[offset], chunk_bytes,
    // cudaMemcpyHostToDevice, streams[i]); cudaMemcpyAsync(&d_arrY[offset],
    // &arrY[offset], chunk_bytes, cudaMemcpyHostToDevice, streams[i]);
    cudaMemcpy(&d_arrX[offset], &arrX[offset], chunk_bytes,
               cudaMemcpyHostToDevice);
    cudaMemcpy(&d_arrY[offset], &arrY[offset], chunk_bytes,
               cudaMemcpyHostToDevice);
    // 启动内核
    XYfixWarp<<<1, 32>>>(&d_arrX[offset], &d_arrY[offset], common.d_negmodn,
                         common.d_negmodn_shoup, common.d_modn,
                         common.d_modn_shoup, common.n, common.mod,
                         common.d_twiddle, common.d_twiddle_shoup,
                         common.d_ICTTwiddle, common.d_ICTTwiddle_shoup,
                         common.d_NCTtwiddle, common.d_NCTtwiddle_shoup,
                         common.d_InvNCTtwiddle, common.d_InvNCTtwiddle_shoup,
                         common.inv, common.inv_shoup, common.d_sample);

    // 异步将结果拷回 Host
    // cudaMemcpyAsync(&arrX[offset], &d_arrX[offset], chunk_bytes,
    // cudaMemcpyDeviceToHost, streams[i]); cudaMemcpyAsync(&arrY[offset],
    // &d_arrY[offset], chunk_bytes, cudaMemcpyDeviceToHost, streams[i]);
    cudaMemcpy(&arrX[offset], &d_arrX[offset], chunk_bytes,
               cudaMemcpyDeviceToHost);
    cudaMemcpy(&arrY[offset], &d_arrY[offset], chunk_bytes,
               cudaMemcpyDeviceToHost);
  }

  // 同步所有流并清理
  cudaDeviceSynchronize();

  for (int i = 0; i < n_streams; i++) {
    cudaStreamDestroy(streams[i]);
  }
  cudaFree(d_arrX);
  cudaFree(d_arrY);
}

void multiStreamVectorTime(uint64_t *arrX, uint64_t *arrY, size_t n_streams,
                           size_t n_blocks, CommonDeviceArrays &common) {
  const int LIMBS = 256;

  size_t chunk_elements = n_blocks * LIMBS;
  size_t chunk_bytes = chunk_elements * sizeof(uint64_t);
  size_t total_bytes = n_streams * chunk_bytes;

  uint64_t *d_arrX, *d_arrY;
  cudaMalloc(&d_arrX, total_bytes);
  cudaMalloc(&d_arrY, total_bytes);

  cudaStream_t *streams = new cudaStream_t[n_streams];
  for (int i = 0; i < n_streams; i++) {
    cudaStreamCreate(&streams[i]);
  }

  // ==========================================
  // 引入 CUDA Event 进行高精度异步计时
  // ==========================================
  cudaEvent_t start_h2d, end_h2d;
  cudaEvent_t start_ker, end_ker;
  cudaEvent_t start_d2h, end_d2h;

  cudaEventCreate(&start_h2d);
  cudaEventCreate(&end_h2d);
  cudaEventCreate(&start_ker);
  cudaEventCreate(&end_ker);
  cudaEventCreate(&start_d2h);
  cudaEventCreate(&end_d2h);

  // 记录 H2D 拷贝开始
  cudaEventRecord(start_h2d, 0);  // 0 表示默认的空流 (串行控制点)

  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;
    cudaMemcpyAsync(&d_arrX[offset], &arrX[offset], chunk_bytes,
                    cudaMemcpyHostToDevice, streams[i]);
    cudaMemcpyAsync(&d_arrY[offset], &arrY[offset], chunk_bytes,
                    cudaMemcpyHostToDevice, streams[i]);
  }

  // 记录 H2D 结束
  cudaEventRecord(end_h2d, 0);

  // ------------------------------------------
  // 记录 Kernel 执行开始
  cudaEventRecord(start_ker, 0);

  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;
    XYfixWarpVector<<<n_blocks, 32, 0, streams[i]>>>(
        &d_arrX[offset], &d_arrY[offset], common.d_negmodn,
        common.d_negmodn_shoup, common.d_modn, common.d_modn_shoup, common.n,
        common.mod, common.d_twiddle, common.d_twiddle_shoup,
        common.d_ICTTwiddle, common.d_ICTTwiddle_shoup, common.d_NCTtwiddle,
        common.d_NCTtwiddle_shoup, common.d_InvNCTtwiddle,
        common.d_InvNCTtwiddle_shoup, common.inv, common.inv_shoup,
        common.d_sample);
  }

  // 记录 Kernel 执行结束
  cudaEventRecord(end_ker, 0);

  // ------------------------------------------
  // 记录 D2H 拷贝开始
  cudaEventRecord(start_d2h, 0);

  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;
    cudaMemcpyAsync(&arrX[offset], &d_arrX[offset], chunk_bytes,
                    cudaMemcpyDeviceToHost, streams[i]);
    cudaMemcpyAsync(&arrY[offset], &d_arrY[offset], chunk_bytes,
                    cudaMemcpyDeviceToHost, streams[i]);
  }

  // 记录 D2H 拷贝结束
  cudaEventRecord(end_d2h, 0);
  // ==========================================

  // 阻塞 CPU，等待 GPU 把所有流的任务以及 Event 打点全部做完
  cudaDeviceSynchronize();

  // ==========================================
  // 提取并计算 Event 记录的物理时间
  // ==========================================
  float ms_h2d = 0, ms_ker = 0, ms_d2h = 0;
  cudaEventElapsedTime(&ms_h2d, start_h2d, end_h2d);
  cudaEventElapsedTime(&ms_ker, start_ker, end_ker);
  cudaEventElapsedTime(&ms_d2h, start_d2h, end_d2h);

  std::cout << "\n=== [深度性能剖析 (基于 CUDA Event)] ===" << std::endl;
  // cudaEventElapsedTime 默认返回毫秒(ms)，我们乘 1000 转为微秒(us)
  std::cout << "1. Host -> Device 拷贝耗时 : " << ms_h2d * 1000.0f << " us"
            << std::endl;
  std::cout << "2. Kernel(s) 并发执行耗时  : " << ms_ker * 1000.0f << " us"
            << std::endl;
  std::cout << "3. Device -> Host 拷贝耗时 : " << ms_d2h * 1000.0f << " us"
            << std::endl;
  std::cout << "=========================================\n" << std::endl;

  // 清理资源
  cudaEventDestroy(start_h2d);
  cudaEventDestroy(end_h2d);
  cudaEventDestroy(start_ker);
  cudaEventDestroy(end_ker);
  cudaEventDestroy(start_d2h);
  cudaEventDestroy(end_d2h);

  for (int i = 0; i < n_streams; i++) {
    cudaStreamDestroy(streams[i]);
  }
  delete[] streams;
  cudaFree(d_arrX);
  cudaFree(d_arrY);
}

void multiStreamVector(uint64_t *arrX, uint64_t *arrY, size_t n_streams,
                       size_t n_blocks, CommonDeviceArrays &common) {
  const int LIMBS = 256;

  // 每个流现在要处理 n_blocks * 256 个元素
  size_t chunk_elements = n_blocks * LIMBS;
  size_t chunk_bytes = chunk_elements * sizeof(uint64_t);
  size_t total_bytes = n_streams * chunk_bytes;

  uint64_t *d_arrX, *d_arrY;
  cudaMalloc(&d_arrX, total_bytes);
  cudaMalloc(&d_arrY, total_bytes);

  // 动态创建 n_streams 个 CUDA 流
  cudaStream_t *streams = new cudaStream_t[n_streams];
  for (int i = 0; i < n_streams; i++) {
    cudaStreamCreate(&streams[i]);
  }

  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;

    // 异步拷贝 H2D
    cudaMemcpyAsync(&d_arrX[offset], &arrX[offset], chunk_bytes,
                    cudaMemcpyHostToDevice, streams[i]);
    cudaMemcpyAsync(&d_arrY[offset], &arrY[offset], chunk_bytes,
                    cudaMemcpyHostToDevice, streams[i]);

    // 启动内核：现在使用的是 <<<n_blocks, 32, 0, streams[i]>>>
    XYfixWarpVector<<<n_blocks, 32, 0, streams[i]>>>(
        &d_arrX[offset], &d_arrY[offset], common.d_negmodn,
        common.d_negmodn_shoup, common.d_modn, common.d_modn_shoup, common.n,
        common.mod, common.d_twiddle, common.d_twiddle_shoup,
        common.d_ICTTwiddle, common.d_ICTTwiddle_shoup, common.d_NCTtwiddle,
        common.d_NCTtwiddle_shoup, common.d_InvNCTtwiddle,
        common.d_InvNCTtwiddle_shoup, common.inv, common.inv_shoup,
        common.d_sample);

    // 异步拷贝 D2H
    cudaMemcpyAsync(&arrX[offset], &d_arrX[offset], chunk_bytes,
                    cudaMemcpyDeviceToHost, streams[i]);
    cudaMemcpyAsync(&arrY[offset], &d_arrY[offset], chunk_bytes,
                    cudaMemcpyDeviceToHost, streams[i]);
  }

  cudaDeviceSynchronize();

  // 清理资源
  for (int i = 0; i < n_streams; i++) {
    cudaStreamDestroy(streams[i]);
  }
  delete[] streams;
  cudaFree(d_arrX);
  cudaFree(d_arrY);
}

void generate_random_array(uint64_t arr[128]) {
  // 初始化随机数种子
  std::srand(static_cast<unsigned int>(std::time(nullptr)));

  for (int i = 0; i < 128; ++i) {
    // 生成0-32767之间的随机数，然后扩展到0-131071
    int r1 = std::rand() & 0x7FFF;  // 0-32767
    int r2 = std::rand() & 0x7FFF;  // 0-32767
    int r3 = std::rand() & 0x7FFF;  // 0-32767
    int r4 = std::rand() & 0x7FFF;  // 0-32767

    // 组合成一个0-131071之间的数
    int combined = ((r1 + r2 + r3 + r4) * 131071) / (4 * 32767);

    // 确保不超出范围
    if (combined > 131071) combined = 131071;
    arr[i] = static_cast<uint64_t>(combined);
  }
}

