// test multiwarp end

void multiStream_m_warps_Time(uint64_t *arrX, uint64_t *arrY, int n_streams,
                              int poly_per_stream, int m,
                              CommonDeviceArrays &common) {
  const int LIMBS = 256;

  // ==========================================
  // 核心维度计算 (升级点)
  // ==========================================
  // 1. 数据量计算：每个流处理的多项式个数 * 256
  size_t chunk_elements = poly_per_stream * LIMBS;
  size_t chunk_bytes = chunk_elements * sizeof(uint64_t);
  size_t total_bytes = n_streams * chunk_bytes;

  // 2. 线程与网格维度计算：
  // 因为 1 个 Block 能吃掉 m 个多项式，所以需要的 Block 数量要除以 m (向上取整)
  int grid_size = (poly_per_stream + m - 1) / m;
  int threads_per_block = m * 32;

  std::cout << "\n[GPU 调度信息] 流数量: " << n_streams
            << ", 每流多项式数: " << poly_per_stream << "\n[Kernel 参数] <<< "
            << grid_size << " Blocks, " << threads_per_block
            << " Threads >>> per stream\n";

  // ==========================================
  // 分配设备端的大显存池
  // ==========================================
  uint64_t *d_arrX, *d_arrY;
  cudaMalloc(&d_arrX, total_bytes);
  cudaMalloc(&d_arrY, total_bytes);

  // 创建 CUDA 流
  cudaStream_t *streams = new cudaStream_t[n_streams];
  for (int i = 0; i < n_streams; i++) {
    cudaStreamCreate(&streams[i]);
  }

  // 引入 CUDA Event 进行高精度异步计时
  cudaEvent_t start_h2d, end_h2d;
  cudaEvent_t start_ker, end_ker;
  cudaEvent_t start_d2h, end_d2h;

  cudaEventCreate(&start_h2d);
  cudaEventCreate(&end_h2d);
  cudaEventCreate(&start_ker);
  cudaEventCreate(&end_ker);
  cudaEventCreate(&start_d2h);
  cudaEventCreate(&end_d2h);

  // ------------------------------------------
  // 1. 记录 H2D 拷贝
  cudaEventRecord(start_h2d, 0);
  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;
    cudaMemcpyAsync(&d_arrX[offset], &arrX[offset], chunk_bytes,
                    cudaMemcpyHostToDevice, streams[i]);
    cudaMemcpyAsync(&d_arrY[offset], &arrY[offset], chunk_bytes,
                    cudaMemcpyHostToDevice, streams[i]);
  }
  cudaEventRecord(end_h2d, 0);

  // ------------------------------------------
  // 2. 记录 Kernel 执行
  cudaEventRecord(start_ker, 0);
  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;

    // 启动内核，精准传入重新计算好的 grid_size 和 threads_per_block
    XYfixWarpVector<<<grid_size, threads_per_block, 0, streams[i]>>>(
        &d_arrX[offset], &d_arrY[offset], common.d_negmodn,
        common.d_negmodn_shoup, common.d_modn, common.d_modn_shoup, common.n,
        common.mod, common.d_twiddle, common.d_twiddle_shoup,
        common.d_ICTTwiddle, common.d_ICTTwiddle_shoup, common.d_NCTtwiddle,
        common.d_NCTtwiddle_shoup, common.d_InvNCTtwiddle,
        common.d_InvNCTtwiddle_shoup, common.inv, common.inv_shoup,
        common.d_sample);
  }
  cudaEventRecord(end_ker, 0);

  // ------------------------------------------
  // 3. 记录 D2H 拷贝
  cudaEventRecord(start_d2h, 0);
  for (int i = 0; i < n_streams; i++) {
    int offset = i * chunk_elements;
    cudaMemcpyAsync(&arrX[offset], &d_arrX[offset], chunk_bytes,
                    cudaMemcpyDeviceToHost, streams[i]);
    cudaMemcpyAsync(&arrY[offset], &d_arrY[offset], chunk_bytes,
                    cudaMemcpyDeviceToHost, streams[i]);
  }
  cudaEventRecord(end_d2h, 0);

  // ==========================================
  // 阻塞 CPU，等待所有异步操作落锤
  // ==========================================
  cudaDeviceSynchronize();

  float ms_h2d = 0, ms_ker = 0, ms_d2h = 0;
  cudaEventElapsedTime(&ms_h2d, start_h2d, end_h2d);
  cudaEventElapsedTime(&ms_ker, start_ker, end_ker);
  cudaEventElapsedTime(&ms_d2h, start_d2h, end_d2h);

  std::cout << "\n=== [m-Warp 多流并发性能剖析] ===" << std::endl;
  std::cout << "1. Host -> Device 拷贝耗时 : " << ms_h2d * 1000.0f << " us"
            << std::endl;
  std::cout << "2. Kernel(s) 并发执行耗时  : " << ms_ker * 1000.0f << " us"
            << std::endl;
  std::cout << "3. Device -> Host 拷贝耗时 : " << ms_d2h * 1000.0f << " us"
            << std::endl;
  std::cout << "=========================================\n" << std::endl;

  // 清理大扫除
  cudaEventDestroy(start_h2d);
  cudaEventDestroy(end_h2d);
  cudaEventDestroy(start_ker);
  cudaEventDestroy(end_ker);
  cudaEventDestroy(start_d2h);
  cudaEventDestroy(end_d2h);

  for (int i = 0; i < n_streams; i++) {
    cudaStreamDestroy(streams[i]);
  }
  delete[] streams;

  // 只释放函数内部申请的局部缓存
  cudaFree(d_arrX);
  cudaFree(d_arrY);
}

#define NLIMBS 256
#define LIMB_BITS 17
#define MASK_17 ((1ULL << 17) - 1)

#define M_CASES 512        // 总测试用例数
#define N_STREAMS 4        // 并发流数
#define N_BLOCKS 8         // 每次内核启动的 block 数
#define WARPS_PER_BLOCK 8  // 每 block 的 warp 数（16×32=512 线程 ≤ 1024）

// 每次内核调用处理的用例数
#define CASES_PER_LAUNCH (N_BLOCKS * WARPS_PER_BLOCK)

// 每流负责的用例数
#define CASES_PER_STREAM ((M_CASES + N_STREAMS - 1) / N_STREAMS)

// 每流需要的内核调用批次数
#define BATCHES_PER_STREAM \
  ((CASES_PER_STREAM + CASES_PER_LAUNCH - 1) / CASES_PER_LAUNCH)

// ---------------------------------------------------------------------------
// CUDA 错误检查
// ---------------------------------------------------------------------------
#define CUDA_CHECK(call)                                              \
  do {                                                                \
    cudaError_t _e = (call);                                          \
    if (_e != cudaSuccess) {                                          \
      fprintf(stderr, "[CUDA Error] %s:%d  %s\n", __FILE__, __LINE__, \
              cudaGetErrorString(_e));                                \
      exit(EXIT_FAILURE);                                             \
    }                                                                 \
  } while (0)

// =============================================================================
// 内核调用宏（带流，grid = n_blocks, block = warps_per_block * 32）
// =============================================================================
#define CALL_XY_S(_nb, _nt, _io, _ioA, _st)                                    \
  XYfixWarpVector<<<(_nb), (_nt), 0, (_st)>>>(                                 \
      (_io), (_ioA), d_negModn, d_con_NegModn_shoup, d_Modn, d_con_Modn_shoup, \
      256, MOD, d_con_twiddle, d_con_twiddle_shoup, d_con_ICTTwiddle,          \
      d_con_ICTTwiddle_shoup, d_con_twiddle_NCT, d_con_twiddle_NCT_shoup,      \
      d_con_InvTwiddle, d_con_InvTwiddle_shoup, inv, inv_shoup, d_sample)

#define CALL_R1_S(_nb, _nt, _io, _st)                                         \
  XYfixWarpROneVector<<<(_nb), (_nt), 0, (_st)>>>(                            \
      (_io), d_r1_ct, d_r1_nct, d_negModn, d_con_NegModn_shoup, d_Modn,       \
      d_con_Modn_shoup, 256, MOD, d_con_twiddle, d_con_twiddle_shoup,         \
      d_con_ICTTwiddle, d_con_ICTTwiddle_shoup, d_con_twiddle_NCT,            \
      d_con_twiddle_NCT_shoup, d_con_InvTwiddle, d_con_InvTwiddle_shoup, inv, \
      inv_shoup, d_sample)

#define CALL_SQ_S(_nb, _nt, _io, _st)                                       \
  XYfixWarpSquareVector<<<(_nb), (_nt), 0, (_st)>>>(                        \
      (_io), d_negModn, d_con_NegModn_shoup, d_Modn, d_con_Modn_shoup, 256, \
      MOD, d_con_twiddle, d_con_twiddle_shoup, d_con_ICTTwiddle,            \
      d_con_ICTTwiddle_shoup, d_con_twiddle_NCT, d_con_twiddle_NCT_shoup,   \
      d_con_InvTwiddle, d_con_InvTwiddle_shoup, inv, inv_shoup, d_sample)

#define CALL_IR_S(_nb, _nt, _io, _st)                                       \
  XYfixWarpIRVector<<<(_nb), (_nt), 0, (_st)>>>(                            \
      (_io), d_negModn, d_con_NegModn_shoup, d_Modn, d_con_Modn_shoup, 256, \
      MOD, d_con_twiddle, d_con_twiddle_shoup, d_con_ICTTwiddle,            \
      d_con_ICTTwiddle_shoup, d_con_twiddle_NCT, d_con_twiddle_NCT_shoup,   \
      d_con_InvTwiddle, d_con_InvTwiddle_shoup, inv, inv_shoup, d_sample)

// =============================================================================
// StreamResource  —  每个流的独立资源
// =============================================================================
struct StreamResource {
  cudaStream_t stream;
  uint64_t *d_x;              // 设备端底数
  uint64_t *d_result;         // 设备端结果
  uint64_t *d_y;              // 工作寄存器 y（整流全部用例）
  uint64_t *d_t;              // 工作寄存器 t
  uint64_t *h_x_pinned;       // 锁页主机底数缓冲
  uint64_t *h_result_pinned;  // 锁页主机结果缓冲
  int cases_in_stream;
};

// =============================================================================
// FMLE_stream_batch()
// 在指定流上，用 n_blocks 个 block（每 block WARPS_PER_BLOCK 个 warp）
// 同时处理 batch_size = n_blocks × WARPS_PER_BLOCK 个用例。
//
// 内核启动维度:
//   grid  = (n_blocks, 1, 1)
//   block = (WARPS_PER_BLOCK * 32, 1, 1)
//
// 内核内部用全局 warp ID 索引数据:
//   global_warp_id = blockIdx.x * WARPS_PER_BLOCK + threadIdx.x / 32
//   data_offset    = global_warp_id * 256
// =============================================================================
static void FMLE_stream_batch(
    uint64_t *d_result_batch, uint64_t *d_x_batch, uint64_t *d_y_buf,
    uint64_t *d_t_buf, const uint64_t *e_limbs, int tau_limbs,
    int n_blocks,  // 本次实际使用的 block 数
    int warps_per_block, cudaStream_t stream, uint64_t *d_r0, uint64_t *d_r1_ct,
    uint64_t *d_r1_nct, uint64_t *d_negModn, uint64_t *d_con_NegModn_shoup,
    uint64_t *d_Modn, uint64_t *d_con_Modn_shoup, uint64_t MOD,
    uint64_t *d_con_twiddle, uint64_t *d_con_twiddle_shoup,
    uint64_t *d_con_ICTTwiddle, uint64_t *d_con_ICTTwiddle_shoup,
    uint64_t *d_con_twiddle_NCT, uint64_t *d_con_twiddle_NCT_shoup,
    uint64_t *d_con_InvTwiddle, uint64_t *d_con_InvTwiddle_shoup, uint64_t inv,
    uint64_t inv_shoup, uint64_t *d_sample) {
  // grid = n_blocks 个 block，每 block = warps_per_block * 32 线程
  const int threads_per_block = warps_per_block * 32;  // ≤ 1024
  const int batch_size = n_blocks * warps_per_block;
  const size_t sz = (size_t)batch_size * NLIMBS * sizeof(uint64_t);

  // 步骤 6: y ← x
  CUDA_CHECK(cudaMemcpyAsync(d_y_buf, d_x_batch, sz, cudaMemcpyDeviceToDevice,
                             stream));

  // 步骤 7: t ← r0（广播到 batch_size 个槽位）
  for (int p = 0; p < batch_size; p++) {
    CUDA_CHECK(cudaMemcpyAsync(d_t_buf + (size_t)p * NLIMBS, d_r0,
                               NLIMBS * sizeof(uint64_t),
                               cudaMemcpyDeviceToDevice, stream));
  }

  // 步骤 8: y ← FMLM(y, r1)
  CALL_R1_S(n_blocks, threads_per_block, d_y_buf, stream);

  // 步骤 9-12: 主循环
  const int tau_bits = tau_limbs * LIMB_BITS;
  for (int i = 0; i < tau_bits; i++) {
    const int bit = (int)((e_limbs[i / LIMB_BITS] >> (i % LIMB_BITS)) & 1ULL);

    // 步骤 10
    if (bit == 1)
      CALL_XY_S(n_blocks, threads_per_block, d_t_buf, d_y_buf, stream);

    // 步骤 11
    CALL_SQ_S(n_blocks, threads_per_block, d_y_buf, stream);
  }

  // 步骤 13: t ← FMLM(t, 1)
  CALL_IR_S(n_blocks, threads_per_block, d_t_buf, stream);

  // 步骤 14: 写出结果
  CUDA_CHECK(cudaMemcpyAsync(d_result_batch, d_t_buf, sz,
                             cudaMemcpyDeviceToDevice, stream));
}

// =============================================================================
// writeLimbsLine — 写 limb 数组到文件（单行）
// =============================================================================
static void writeLimbsLine(FILE *fp, const uint64_t *a, int len) {
  for (int i = 0; i < len; i++) {
    fprintf(fp, "%llu", (unsigned long long)a[i]);
    if (i < len - 1) fprintf(fp, ",");
  }
  fprintf(fp, "\n");
}

