  // ============================================================
  // [paillier_encryptionhs 性能测试]
  // Enc(m_i, r_i) = (1 + m_i·n) · h_s^{r_i}  mod n²（FMLM域）
  // Step① Getrn：10-bit 窗口查表计算 h̃_s^{r_i}（FMLM域）
  // Step② compute_plain_factor_batch_kernel：(1+m·n) mod n²（标准域）
  // Step③ XYfixWarpROneVector：(1+m·n) → FMLM域
  // Step④ XYfixWarpVector：(1̃+m·n) · h̃_s^{r_i} → c̃（FMLM域）
  // 结果写入 encryption_results.txt，供 verify_encryptionhs.py 验证正确性。
  // ============================================================
  const int NUM_ENC = 1000;
  const int kWarmup = 3;
  const int kRounds = 2;
  // ── 参数定义 ─────────────────────────────────────────────────────────────
  const int TAU_R = 1024;            // r ← Z_{2^{k/2}}，k=2048
  const int EXP_R_U64 = TAU_R / 64;  // = 16
  const size_t ct_bytes = (size_t)NUM_ENC * ARR_LEN * sizeof(uint64_t);
  const size_t m_bytes = (size_t)NUM_ENC * ARR_LEN * sizeof(uint64_t);
  const size_t r_bytes = (size_t)NUM_ENC * EXP_R_U64 * sizeof(uint64_t);
  const size_t tbl_bytes = (size_t)TABLE_SIZE * ARR_LEN * sizeof(uint64_t);

  printf("\n============================================================\n");
  printf("  [paillier_encryptionhs] 批量加密性能测试\n");
  printf("  批大小=%d  TAU_R=%d bit  WINDOW=%d bit  TABLE_SIZE=%d 项\n",
         NUM_ENC, TAU_R, WINDOW_BITS, TABLE_SIZE);
  printf("  窗口数=%d（每窗口 %d 次平方 + 1 次乘法）\n",
         (TAU_R + WINDOW_BITS - 1) / WINDOW_BITS, WINDOW_BITS);
  printf("============================================================\n");

  // ── 1. CPU 建立 hs 预计算表 ──────────────────────────────────────────────
  uint64_t h_hs[ARR_LEN] = {};
  uint64_t *h_table = (uint64_t *)malloc(tbl_bytes);
  if (!h_table) {
    fprintf(stderr, "[Enc] h_table malloc 失败\n");
    goto enc_done;
  }
  generate_hs_table(N2_arr, h_hs, h_table);

  {
    // ── 2. 分配 pinned 内存 ───────────────────────────────────────────────
    uint64_t *h_m = NULL;   // 明文 m（标准域，base-2^BASE_BITS）
    uint64_t *h_r = NULL;   // 随机指数 r_i（1024-bit，各独立）
    uint64_t *h_ct = NULL;  // D2H 后密文结果
    CUDA_CHECK(cudaMallocHost(&h_m, m_bytes));
    CUDA_CHECK(cudaMallocHost(&h_r, r_bytes));
    CUDA_CHECK(cudaMallocHost(&h_ct, ct_bytes));

    // ── 3. 随机生成输入数据 ───────────────────────────────────────────────
    srand((unsigned int)time(NULL));
    const uint64_t mask17 = (1ULL << BASE_BITS) - 1;
    // m < n：使用 N_WORDS-1=120 个随机 limb（limb 120..255 填 0），保证 m < n
    for (int p = 0; p < NUM_ENC; p++) {
      uint64_t *mp = h_m + (size_t)p * ARR_LEN;
      for (int j = 0; j < ARR_LEN; j++) {
        if (j < N_WORDS - 1)  // 0..119：随机 limb in [0, BASE)
          mp[j] = ((uint64_t)(uint32_t)rand() ^
                   ((uint64_t)(uint32_t)rand() << 15)) &
                  mask17;
        else
          mp[j] = 0ULL;  // 120..255：填 0，确保 m < n
      }
    }
    // r_i：各独立的 1024-bit 随机数
    for (int p = 0; p < NUM_ENC; p++) {
      uint64_t *rp = h_r + (size_t)p * EXP_R_U64;
      for (int j = 0; j < EXP_R_U64; j++)
        rp[j] = ((uint64_t)(uint32_t)rand() << 32) | (uint64_t)(uint32_t)rand();
    }
    printf("[Enc] 随机数据生成完成（%d 个明文，各 %d-bit r_i）\n", NUM_ENC,
           TAU_R);

    // ── 4. 分配 GPU 内存 & H2D ────────────────────────────────────────────
    uint64_t *d_table = NULL;
    uint64_t *d_m = NULL;
    uint64_t *d_r = NULL;
    uint64_t *d_ct_out = NULL;
    CUDA_CHECK(cudaMalloc(&d_table, tbl_bytes));
    CUDA_CHECK(cudaMalloc(&d_m, m_bytes));
    CUDA_CHECK(cudaMalloc(&d_r, r_bytes));
    CUDA_CHECK(cudaMalloc(&d_ct_out, ct_bytes));
    {
      struct timespec t0h, t1h;
      clock_gettime(CLOCK_MONOTONIC, &t0h);
      CUDA_CHECK(
          cudaMemcpy(d_table, h_table, tbl_bytes, cudaMemcpyHostToDevice));
      CUDA_CHECK(cudaMemcpy(d_m, h_m, m_bytes, cudaMemcpyHostToDevice));
      CUDA_CHECK(cudaMemcpy(d_r, h_r, r_bytes, cudaMemcpyHostToDevice));
      clock_gettime(CLOCK_MONOTONIC, &t1h);
      double h2d_ms = (double)(t1h.tv_sec - t0h.tv_sec) * 1e3 +
                      (double)(t1h.tv_nsec - t0h.tv_nsec) * 1e-6;
      printf("[Enc] H2D: %.3f ms  表 %.2f MB + 明文 %.2f MB + 指数 %.2f MB\n",
             h2d_ms, tbl_bytes / 1048576.0, m_bytes / 1048576.0,
             r_bytes / 1048576.0);
    }

    // ── 5. 预热 ───────────────────────────────────────────────────────────
    printf("[Enc] 预热 %d 次...\n", kWarmup);
    for (int w = 0; w < kWarmup; w++) {
      paillier_encryptionhs(
          d_m, d_ct_out, d_N, d_N2, d_table, d_r, TAU_R, NUM_ENC, d_ctR, d_nctR,
          d_negModn, d_con_NegModn_shoup, d_Modn, d_con_Modn_shoup, MOD,
          d_con_twiddle, d_con_twiddle_shoup, d_con_ICTTwiddle,
          d_con_ICTTwiddle_shoup, d_con_twiddle_NCT, d_con_twiddle_NCT_shoup,
          d_con_InvTwiddle, d_con_InvTwiddle_shoup, inv, inv_shoup, d_sample);
      CUDA_CHECK(cudaDeviceSynchronize());
    }
    printf("[Enc] 预热完成\n\n");

    // ── 6. cudaEvent 计时（d_m/d_r 只读，d_ct_out 每轮写入，无需重置）──────
    printf("[Enc] 开始计时（%d 轮 × %d 个明文）...\n", kRounds, NUM_ENC);
    float rms[5] = {};
    for (int rnd = 0; rnd < kRounds; rnd++) {
      rms[rnd] = paillier_encryptionhs(
          d_m, d_ct_out, d_N, d_N2, d_table, d_r, TAU_R, NUM_ENC, d_ctR, d_nctR,
          d_negModn, d_con_NegModn_shoup, d_Modn, d_con_Modn_shoup, MOD,
          d_con_twiddle, d_con_twiddle_shoup, d_con_ICTTwiddle,
          d_con_ICTTwiddle_shoup, d_con_twiddle_NCT, d_con_twiddle_NCT_shoup,
          d_con_InvTwiddle, d_con_InvTwiddle_shoup, inv, inv_shoup, d_sample);
    }
    printf("[Enc] 计时完成\n\n");

    // ── 7. D2H 最后一轮密文结果 ──────────────────────────────────────────
    {
      struct timespec t0d, t1d;
      clock_gettime(CLOCK_MONOTONIC, &t0d);
      CUDA_CHECK(cudaMemcpy(h_ct, d_ct_out, ct_bytes, cudaMemcpyDeviceToHost));
      clock_gettime(CLOCK_MONOTONIC, &t1d);
      double d2h_ms = (double)(t1d.tv_sec - t0d.tv_sec) * 1e3 +
                      (double)(t1d.tv_nsec - t0d.tv_nsec) * 1e-6;
      printf("[Enc] D2H: %.3f ms  密文 %.2f MB\n", d2h_ms,
             ct_bytes / 1048576.0);
    }

    // ── 8. 写结果到 encryption_results.txt ──────────────────────────────
    // 格式（供 verify_encryptionhs.py 验证）：
    //   行1: NUM_ENC ARR_LEN BASE_BITS TAU_R
    //   行2: n² limbs（ARR_LEN 个 uint64，base-2^BASE_BITS，小端序）
    //   行3: n  limbs（ARR_LEN 个 uint64）
    //   行4: r_param = table[0]（FMLM 恒等元）
    //   行5: hs limbs（ARR_LEN 个 uint64，标准域）
    //   每个用例 3 行：m limbs / r_i limbs / c̃ limbs
    {
      FILE *fout = fopen("encryption_results.txt", "w");
      if (!fout) {
        fprintf(stderr, "[Enc] 无法创建 encryption_results.txt\n");
      } else {
        fprintf(fout, "%d %d %d %d\n", NUM_ENC, ARR_LEN, BASE_BITS, TAU_R);
        // n²
        for (int j = 0; j < ARR_LEN; j++)
          fprintf(fout, "%llu%c", (unsigned long long)N2_arr[j],
                  j + 1 < ARR_LEN ? ' ' : '\n');
        // n
        for (int j = 0; j < ARR_LEN; j++)
          fprintf(fout, "%llu%c", (unsigned long long)N_arr[j],
                  j + 1 < ARR_LEN ? ' ' : '\n');
        // r_param = table[0]（FMLM 恒等元）
        for (int j = 0; j < ARR_LEN; j++)
          fprintf(fout, "%llu%c", (unsigned long long)h_table[j],
                  j + 1 < ARR_LEN ? ' ' : '\n');
        // hs（底数，标准域）
        for (int j = 0; j < ARR_LEN; j++)
          fprintf(fout, "%llu%c", (unsigned long long)h_hs[j],
                  j + 1 < ARR_LEN ? ' ' : '\n');
        // 每个用例 3 行
        for (int p = 0; p < NUM_ENC; p++) {
          const uint64_t *mp = h_m + (size_t)p * ARR_LEN;
          const uint64_t *rp = h_r + (size_t)p * EXP_R_U64;
          const uint64_t *ctp = h_ct + (size_t)p * ARR_LEN;
          // m（明文，标准域）
          for (int j = 0; j < ARR_LEN; j++)
            fprintf(fout, "%llu%c", (unsigned long long)mp[j],
                    j + 1 < ARR_LEN ? ' ' : '\n');
          // r_i（随机指数，16 个 uint64）
          for (int j = 0; j < EXP_R_U64; j++)
            fprintf(fout, "%llu%c", (unsigned long long)rp[j],
                    j + 1 < EXP_R_U64 ? ' ' : '\n');
          // c̃（密文，FMLM域）
          for (int j = 0; j < ARR_LEN; j++)
            fprintf(fout, "%llu%c", (unsigned long long)ctp[j],
                    j + 1 < ARR_LEN ? ' ' : '\n');
        }
        fclose(fout);
        printf("[Enc] 结果已写入 encryption_results.txt\n");
      }
    }

    // ── 9. 性能统计 ───────────────────────────────────────────────────────
    float rmin = rms[0], rmax = rms[0], rsum = 0.f;
    for (int rnd = 0; rnd < kRounds; rnd++) {
      rsum += rms[rnd];
      if (rms[rnd] < rmin) rmin = rms[rnd];
      if (rms[rnd] > rmax) rmax = rms[rnd];
    }
    float ravg = rsum / kRounds;
    printf("\n============================================================\n");
    printf("  paillier_encryptionhs 性能报告\n");
    printf("  批大小=%d  TAU_R=%d bit  WINDOW=%d bit\n", NUM_ENC, TAU_R,
           WINDOW_BITS);
    printf("============================================================\n");
    printf("[计时结果（cudaEvent，仅 GPU 核函数，不含传输）]\n");
    printf("------------------------------------------------------------\n");
    for (int rnd = 0; rnd < kRounds; rnd++)
      printf("  轮 %d : %8.3f ms  (%.3f us/次)\n", rnd, rms[rnd],
             rms[rnd] * 1e3f / NUM_ENC);
    printf("------------------------------------------------------------\n");
    printf("  平均每轮总耗时       : %8.3f ms\n", ravg);
    printf("  最快轮               : %8.3f ms\n", rmin);
    printf("  最慢轮               : %8.3f ms\n", rmax);
    printf("  平均单次 Encrypt     : %8.3f us\n", ravg * 1e3f / NUM_ENC);
    printf("  (最快轮) 单次        : %8.3f us\n", rmin * 1e3f / NUM_ENC);
    printf("============================================================\n");

    // ── 10. 释放 Encryption 相关内存 ──────────────────────────────────────
    cudaFreeHost(h_m);
    cudaFreeHost(h_r);
    cudaFreeHost(h_ct);
    cudaFree(d_table);
    cudaFree(d_m);
    cudaFree(d_r);
    cudaFree(d_ct_out);
  }
  free(h_table);
  printf("[Enc] 测试完成\n");
enc_done:;

  // ── 11. 释放公共设备资源 ──────────────────────────────────────────────────
  cudaFree(d_Modn);
  cudaFree(d_negModn);
  cudaFree(d_nctR);
  cudaFree(d_ctR);
  cudaFree(d_r_0);
  cudaFree(d_N);
  cudaFree(d_N2);
  cudaFree(d_con_twiddle);
  cudaFree(d_con_twiddle_shoup);
  cudaFree(d_con_twiddle_NCT);
  cudaFree(d_con_twiddle_NCT_shoup);
  cudaFree(d_con_ICTTwiddle);
  cudaFree(d_con_ICTTwiddle_shoup);
  cudaFree(d_con_InvTwiddle);
  cudaFree(d_con_InvTwiddle_shoup);
  cudaFree(d_con_Modn_shoup);
  cudaFree(d_con_NegModn_shoup);
  cudaFree(d_sample);

  printf("\n[DONE] paillier_encryptionhs 测试完成。\n");
  return 0;

  /*
  cudaFree(d_sample);
  cudaFree(d_con_twiddle);
  cudaFree(d_con_twiddle_shoup);
  cudaFree(d_con_twiddle_NCT);
  cudaFree(d_con_twiddle_NCT_shoup);
  cudaFree(d_con_InvTwiddle);
  cudaFree(d_con_InvTwiddle_shoup);
  cudaFree(d_con_ICTTwiddle);
  cudaFree(d_con_ICTTwiddle_shoup);
  cudaFree(d_Modn);
  cudaFree(d_negModn);
  cudaFree(d_con_Modn_shoup);
  cudaFree(d_con_NegModn_shoup);


  //free(arrX);
  //free(arrY);
*/
  // 重置设备状态 (可选，但推荐，方便性能分析工具 profiling)
  cudaDeviceReset();
}
